async ingestFiles(fileList) {
    if (!fileList.length) return;

    // Enforce the 3-file cap before uploading anything.
    const totalAfter = this.files.length + fileList.length;
    if (totalAfter > MAX_FILES) {
        this.error = `Maximum ${MAX_FILES} files allowed. You have ${this.files.length} file(s) — remove one before adding more.`;
        return;
